    actor: "admin@kiln.dev",
  };
  const entry = auditEntry(req, "pause_org", new Date("2026-11-17T12:00:00Z"));
  assert.equal(entry.actor, "admin@kiln.dev");
  assert.equal(entry.action, "pause_org");
  assert.equal(entry.route, "POST /admin/pause-org");
  assert.equal(entry.timestamp, "2026-11-17T12:00:00.000Z");
  assert.equal(entry.request_id, "req_123");
});

